package com.pointverse.app;

import org.json.*;
import java.util.*;

/** Camera and spherical picking are independent of rendering and screen density. */
final class UniverseScene {
    static final class V {final double x,y,z;V(double x,double y,double z){this.x=x;this.y=y;this.z=z;}V unit(){double n=Math.sqrt(x*x+y*y+z*z);return n<1e-9?new V(0,0,1):new V(x/n,y/n,z/n);}double dot(V b){return x*b.x+y*b.y+z*b.z;}}
    static final class Rotation {
        final double[] m;Rotation(){m=new double[]{1,0,0,0,1,0,0,0,1};}Rotation(double[] m){this.m=m;}
        V apply(V p){return new V(m[0]*p.x+m[1]*p.y+m[2]*p.z,m[3]*p.x+m[4]*p.y+m[5]*p.z,m[6]*p.x+m[7]*p.y+m[8]*p.z);}
        Rotation times(Rotation b){double[] r=new double[9];for(int i=0;i<3;i++)for(int j=0;j<3;j++)for(int k=0;k<3;k++)r[i*3+j]+=m[i*3+k]*b.m[k*3+j];return new Rotation(r);}
        static Rotation x(double a){double c=Math.cos(a),s=Math.sin(a);return new Rotation(new double[]{1,0,0,0,c,-s,0,s,c});}static Rotation y(double a){double c=Math.cos(a),s=Math.sin(a);return new Rotation(new double[]{c,0,s,0,1,0,-s,0,c});}
        static Rotation face(V p){double yaw=Math.atan2(-p.x,p.z);V r=y(yaw).apply(p);return x(Math.atan2(r.y,r.z)).times(y(yaw));}
    }
    static final class State {
        double cameraX,cameraY,distance=24,elapsed,panX,panY,treeZoom=1;boolean initialized,demo;String target="",focused="",selectedTree="";final Map<String,Rotation> rotations=new HashMap<>();final Set<String> expanded=new HashSet<>();long pauseUntil;
        String json(){try{JSONObject o=new JSONObject().put("x",cameraX).put("y",cameraY).put("d",distance).put("elapsed",elapsed).put("px",panX).put("py",panY).put("tz",treeZoom).put("init",initialized).put("demo",demo).put("target",target).put("focus",focused).put("selectedTree",selectedTree).put("expanded",new JSONArray(expanded));JSONObject rotationsJSON=new JSONObject();for(Map.Entry<String,Rotation> e:rotations.entrySet()){JSONArray a=new JSONArray();for(double x:e.getValue().m)a.put(x);rotationsJSON.put(e.getKey(),a);}return o.put("rotations",rotationsJSON).toString();}catch(JSONException e){return "{}";}}
        static State parse(String raw){State s=new State();try{JSONObject o=new JSONObject(raw);s.cameraX=finite(o.optDouble("x",0),0);s.cameraY=finite(o.optDouble("y",0),0);s.distance=finite(o.optDouble("d",24),24);s.elapsed=finite(o.optDouble("elapsed",0),0);s.panX=finite(o.optDouble("px",0),0);s.panY=finite(o.optDouble("py",0),0);s.treeZoom=Math.max(.001,Math.min(4,finite(o.optDouble("tz",1),1)));s.initialized=o.optBoolean("init");s.demo=o.optBoolean("demo");s.target=o.optString("target");s.focused=o.optString("focus");s.selectedTree=o.optString("selectedTree");JSONArray a=o.optJSONArray("expanded");if(a!=null)for(int i=0;i<a.length();i++)s.expanded.add(a.optString(i));JSONObject r=o.optJSONObject("rotations");if(r!=null)for(Iterator<String> keys=r.keys();keys.hasNext();){String key=keys.next();JSONArray values=r.optJSONArray(key);if(values==null||values.length()!=9)continue;double[] m=new double[9];for(int i=0;i<9;i++)m[i]=finite(values.optDouble(i),i%4==0?1:0);s.rotations.put(key,new Rotation(m));}}catch(Exception ignored){}return s;}
        static double finite(double x,double fallback){return Double.isFinite(x)?x:fallback;}
    }
    static final class Node {final PointStore.Point point;final String topic;final V unit;Node(PointStore.Point point,String topic,V unit){this.point=point;this.topic=topic;this.unit=unit;}}
    static final class Planet {final String id,name;final int galaxy,order;final List<Node> nodes=new ArrayList<>();final double radius;Planet(String id,int galaxy,int order,int count){this.id=id;this.name=id+"星球";this.galaxy=galaxy;this.order=order;radius=planetRadius(count);}}
    static final class Projection {final double x,y,r,depth,scale;Projection(double x,double y,double r,double depth,double scale){this.x=x;this.y=y;this.r=r;this.depth=depth;this.scale=scale;}}
    static final class Cluster {final List<Node> members;final V unit;Cluster(List<Node> members,V unit){this.members=members;this.unit=unit;}}
    private final Map<String,Object[]> clusterCache=new HashMap<>();
    final State state;final List<Planet> planets=new ArrayList<>();final Map<String,Planet> owner=new HashMap<>();final Map<String,Node> nodes=new HashMap<>();
    UniverseScene(List<PointStore.Point> points,SemanticIndex index,State state){this.state=state;Map<String,List<PointStore.Point>> groups=new TreeMap<>();for(PointStore.Point p:points){String key=index.value(p,"domain");groups.computeIfAbsent(key.isEmpty()?"待整理":key,k->new ArrayList<>()).add(p);}List<String> ordered=new ArrayList<>(groups.keySet());ordered.sort((a,b)->{int cmp=Integer.compare(groups.get(b).size(),groups.get(a).size());return cmp==0?a.compareTo(b):cmp;});int systems=Math.min(3,Math.max(1,(int)Math.ceil(Math.sqrt(ordered.size()/3.0))));for(int n=0;n<ordered.size();n++){String key=ordered.get(n);Planet p=new Planet(key,n%systems,n/systems,groups.get(key).size());List<PointStore.Point> members=groups.get(key);members.sort(Comparator.comparing(a->a.id));for(PointStore.Point point:members){String topic=index.value(point,"topic");V center=seedUnit(topic.isEmpty()?key:topic);V jitter=seedUnit(point.id);V position=new V(center.x+.55*jitter.x,center.y+.55*jitter.y,center.z+.55*jitter.z).unit();if(state.demo)try{JSONArray vector=new JSONArray(point.embedding);if(vector.length()==3)position=new V(vector.getDouble(0),vector.getDouble(1),vector.getDouble(2)).unit();}catch(Exception ignored){}Node node=new Node(point,topic.isEmpty()?"未分主题":topic,position);p.nodes.add(node);owner.put(point.id,p);nodes.put(point.id,node);}planets.add(p);}if(planet(state.target)==null)state.target="";if(!nodes.containsKey(state.focused))state.focused="";}
    static double planetRadius(int count){return .48+.70*(1-Math.exp(-Math.sqrt(Math.max(0,count))/10));}
    static double starRadius(int pointCount,double pointsPerWorldUnit){double world=Math.min(1.65,.8+Math.sqrt(Math.max(0,pointCount))*.025);return Math.max(8,Math.min(40,world*Math.max(0,pointsPerWorldUnit)));}
    static double clickedDiameter(double w,double h){return w>0&&h>0?Math.min(w*.88,h*.56):0;}
    static double flight(double from,double to,double t){if(from<=0||to<=0||!Double.isFinite(from)||!Double.isFinite(to))return from;double q=Math.max(0,Math.min(1,t)),ease=q*q*(3-2*q);return Math.exp(Math.log(from)+(Math.log(to)-Math.log(from))*ease);}
    static double orbitDelta(double previous,double now,double resume){return !Double.isFinite(previous)||!Double.isFinite(now)||!Double.isFinite(resume)?0:Math.min(.1,Math.max(0,now-Math.max(previous,resume)));}
    static V seedUnit(String value){Random r=new Random(value.hashCode()*0x9e3779b97f4a7c15L);double z=r.nextDouble()*2-1,angle=r.nextDouble()*Math.PI*2,radial=Math.sqrt(1-z*z);return new V(radial*Math.cos(angle),radial*Math.sin(angle),z);}
    Planet planet(String id){for(Planet p:planets)if(p.id.equals(id))return p;return null;}
    int systemCount(){int n=0;for(Planet p:planets)n=Math.max(n,p.galaxy+1);return n;}
    V system(int index){if(systemCount()==1)return new V(0,0,0);double a=index*2.399963;return new V(Math.cos(a)*9,Math.sin(a)*6,index*.8);}
    double orbitRadius(Planet p){return 2.1+p.order*1.9;}
    V world(Planet p){V center=system(p.galaxy);double a=(p.id.hashCode()&0x7fffffff)*.00013+state.elapsed*2*Math.PI/(180+p.order*70),r=orbitRadius(p);return new V(center.x+Math.cos(a)*r,center.y+Math.sin(a)*r*.62,center.z+Math.sin(a)*r*.35);}
    Projection project(Planet p,double w,double h){V v=world(p);double gap=state.distance-v.z;if(gap<=.02)return null;double scale=Math.min(w,h)*1.15/gap;return new Projection(w/2+(v.x-state.cameraX)*scale,h/2-(v.y-state.cameraY)*scale,p.radius*scale,v.z,scale);}
    Rotation rotation(Planet p){return state.rotations.getOrDefault(p.id,new Rotation());}
    void rotate(Planet p,double dx,double dy,double radius){state.rotations.put(p.id,Rotation.x(dy/Math.max(80,radius)).times(Rotation.y(dx/Math.max(80,radius))).times(rotation(p)));}
    void pan(double dx,double dy,double w,double h){Planet target=planet(state.target);double gap=target==null?state.distance:state.distance-world(target).z,scale=Math.min(w,h)*1.15/Math.max(.02,gap);state.cameraX-=dx/Math.max(1,scale);state.cameraY+=dy/Math.max(1,scale);}
    void magnify(double factor,Planet anchor,double w,double h){if(!Double.isFinite(factor)||factor<=0)return;factor=Math.max(.1,Math.min(10,factor));if(anchor!=null){Projection before=project(anchor,w,h);if(before==null)return;V p=world(anchor);double gap=Math.max(.01,Math.min(1e6,(state.distance-p.z)/factor));state.distance=p.z+gap;double scale=Math.min(w,h)*1.15/gap;state.cameraX=p.x-(before.x-w/2)/scale;state.cameraY=p.y+(before.y-h/2)/scale;state.target=anchor.id;if(before.r*2*factor<reveal(w,h)*.72)state.target="";}else state.distance=Math.max(.1,Math.min(1e6,state.distance/factor));}
    static double reveal(double w,double h){return Math.max(84,Math.min(w,h)*.26);}
    double[] destination(Planet p,double diameter,double w,double h){V world=world(p);return new double[]{world.x,world.y,world.z+p.radius*2*Math.min(w,h)*1.15/Math.max(.1,diameter)};}
    double[] overview(double w,double h){if(planets.isEmpty())return new double[]{0,0,24};double minX=1e9,maxX=-1e9,minY=1e9,maxY=-1e9,maxZ=-1e9;for(Planet p:planets){V v=world(p);double orbit=orbitRadius(p),padding=Math.max(p.radius,orbit*.2);minX=Math.min(minX,v.x-padding);maxX=Math.max(maxX,v.x+padding);minY=Math.min(minY,v.y-padding);maxY=Math.max(maxY,v.y+padding);maxZ=Math.max(maxZ,v.z);}for(int g=0;g<systemCount();g++){V star=system(g);minX=Math.min(minX,star.x-1.65);maxX=Math.max(maxX,star.x+1.65);minY=Math.min(minY,star.y-1.65);maxY=Math.max(maxY,star.y+1.65);maxZ=Math.max(maxZ,star.z);}double gap=Math.max((maxX-minX)*Math.min(w,h)*1.15/Math.max(1,w*.8),(maxY-minY)*Math.min(w,h)*1.15/Math.max(1,h*.7));return new double[]{(minX+maxX)/2,(minY+maxY)/2,maxZ+Math.max(5,gap)};}
    @SuppressWarnings("unchecked") List<Cluster> clusters(Planet p,double radius){long bucket=(long)(Math.log(Math.max(1,radius))*128);int hash=p.nodes.hashCode();Object[] cached=clusterCache.get(p.id);if(cached!=null&&(long)cached[0]==bucket&&(int)cached[1]==hash)return (List<Cluster>)cached[2];double angle=Math.max(.002,30/Math.max(1,radius));List<Node> remaining=new ArrayList<>(p.nodes);List<Cluster> result=new ArrayList<>();while(!remaining.isEmpty()){Node seed=remaining.remove(0);List<Node> members=new ArrayList<>();members.add(seed);double x=seed.unit.x,y=seed.unit.y,z=seed.unit.z;for(Iterator<Node> it=remaining.iterator();it.hasNext();){Node n=it.next();if(!seed.point.id.equals(state.focused)&&!n.point.id.equals(state.focused)&&Math.acos(Math.max(-1,Math.min(1,seed.unit.dot(n.unit))))<=angle){members.add(n);x+=n.unit.x;y+=n.unit.y;z+=n.unit.z;it.remove();}}result.add(new Cluster(members,new V(x,y,z).unit()));}clusterCache.put(p.id,new Object[]{bucket,hash,result});return result;}
    void advance(double seconds){Planet target=planet(state.target);V before=target==null?null:world(target);state.elapsed+=seconds;if(target!=null){V after=world(target);state.cameraX+=after.x-before.x;state.cameraY+=after.y-before.y;state.distance+=after.z-before.z;}}
}
